# Read mbox-format messages and put them into the %spam hash keyed by
# message MD5.

use Digest::MD5;
my ($currmsg, $currmsgref) = ('', []);

while (<DATA>) {
  if (/^From /) {       # Start of new message
    if ($currmsg ne '') {
      $spam{Digest::MD5->md5_hex($currmsg)} = $currmsgref;
    }
    $currmsg = '';
    $currmsgref = [];
  }
  $currmsg .= $_;
  push @$currmsgref, $_;
}

1;
